sys_script_fix.script:
var nowDateTime = new GlideDateTime(); // Safe in scoped apps

var taskGR = new GlideRecord('x_1790229_event_ma_event_task'); // Your task table
taskGR.addQuery('u_due_date', '<', nowDateTime); // Replace with your due date field
taskGR.addQuery('u_status', '!=', 'cancelled');  // Adjust field and value if needed
taskGR.query();

while (taskGR.next()) {
    taskGR.u_status = 'cancelled'; // Use the internal value, not display name if different
    taskGR.update();
    gs.info('Task "' + taskGR.getDisplayValue('u_task_name') + '" is overdue and marked as Cancelled.');
}
